        *(int32_t *)(v46 - 36) = *v26;
        *(int32_t *)(v46 - 40) = *v4;
        int32_t * v51 = (int32_t *)(v46 - 44); // 0x409fff
        *v51 = *v47;
        int32_t * v52 = (int32_t *)(v46 - 48); // 0x40a004
        *v52 = v50;
