        *(int32_t *)(data + 4) = before + 1;
        if (retdec_is_init_savedata_closure(type, data))
            retdec_trace_init_ref_event(
                "add", type, data, before, before + 1,
                (int32_t)(uintptr_t)_ReturnAddress());
        retdec_trace("sq-addref-done");
