        retdec_trace_i32("sq-watch:raw-release-caller",
                         (int32_t)(uintptr_t)_ReturnAddress());
        retdec_trace_ref_watch("raw-release-before",
                               retdec_primary_shared_state, type, data);
        retdec_trace_i32("sq-watch:raw-release-site",
                         (int32_t)(uintptr_t)_ReturnAddress());
