        buckets = *(int32_t *)(intptr_t)(table_ptr + 16);
        bucket_index = (int32_t)(retdec_squirrel_key_hash(key) &
                                 (uint32_t)(slots - 1));
        bucket = buckets + 4 * bucket_index;
