    *(int32_t *)(intptr_t)(table_ptr + 12) =
        *(int32_t *)(intptr_t)(node + 12);
    *(int32_t *)(intptr_t)(node + 0) = type;
    *(int32_t *)(intptr_t)(node + 4) = data;
    *(int32_t *)(intptr_t)(node + 8) = 1;
    *(int32_t *)(intptr_t)(node + 12) =
        *(int32_t *)(intptr_t)bucket;
